{
    "instruction": "Provide a short PowerShell script that continuously monitors GPU temperature on a Windows 11 machine and logs any reading above 85 °C to a file.",
    "response": "powershell
# Requires the NVIDIA PowerShell module (Install-Module -Name NvidiaGPU)
Import-Module NvidiaGPU
$logPath = "C:\Logs\GPU_Temp_Alerts.log"
while ($true) {
    $temp = Get-NvidiaGPU -Property Temperature | Select-Object -ExpandProperty Temperature
    if ($temp -gt 85) {
        $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
        "[$timestamp] GPU temperature high: $temp°C" | Out-File -FilePath $logPath -Append -Encoding utf8
    }

